def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core, _ = core.split('+', 1)
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def cmp_ids(a_ids, b_ids):
        if a_ids is None and b_ids is None:
            return 0
        if a_ids is None:
            return 1
        if b_ids is None:
            return -1
        for a, b in zip(a_ids, b_ids):
            if a == b:
                continue
            a_num = a.isdigit()
            b_num = b.isdigit()
            if a_num and b_num:
                ai, bi = int(a), int(b)
                if ai != bi:
                    return -1 if ai < bi else 1
                continue
            if a_num and not b_num:
                return -1
            if not a_num and b_num:
                return 1
            return -1 if a < b else 1
        if len(a_ids) == len(b_ids):
            return 0
        return -1 if len(a_ids) < len(b_ids) else 1

    def cmp(v1, v2):
        p1 = parse(v1)
        p2 = parse(v2)
        for i in range(3):
            if p1[i] != p2[i]:
                return -1 if p1[i] < p2[i] else 1
        return cmp_ids(p1[3], p2[3])

    import functools
    return sorted(versions, key=functools.cmp_to_key(cmp))

